// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Run a list of page steps at human pace with halt checks and popup handling
// Flo: pause flag > pace delay > find by role + label (retry) > scroll > click, type, select, toggle, hover > halt check (dialog-scoped) > popups dismissed after each page load
// I/O: Steps + Run (page, rng, conf, state) > page effects; errors Halted Unsafe NeedLogin NoElement Drift Paused
// ===================================================================
const std = @import("std"); const pg = @import("ru-page-snap.zig"); const inpu = @import("ru-huma-inpu.zig"); const pace = @import("ru-huma-pace.zig"); const halt = @import("ru-safe-halt.zig"); const stat = @import("st-stat-main.zig"); const fld = @import("ut-text-fold.zig"); const pack = @import("ut-loca-pack.zig");
const CF = .{ .retr_nap = 400, .expe_dflt = 6000, .flag_paus = "pause", .dlgs = "Array.from(document.querySelectorAll('[role=dialog],[role=alert]')).filter(function(e){return !e.hidden&&e.getClientRects().length>0}).map(function(e){return e.innerText}).join('\\n')", .dlgn = "Array.from(document.querySelectorAll('[role=dialog]')).filter(function(e){return !e.hidden&&e.getClientRects().length>0}).length", .ison = "function(){return this.checked===true||this.getAttribute('aria-checked')==='true'}", .opts = [_][]const u8{ "option", "menuitem", "radio", "menuitemradio", "listitem", "button", "" }, .dwel_lo = 600, .dwel_hi = 2500 };
pub const Op = enum { goto, click, typez, key, wait, expect, scroll, upload, hover, select, toggle, confirm, clear, dismiss };
pub const Step = struct { op: Op, role: []const u8 = "", labs: []const []const u8 = &.{}, text: []const u8 = "", nth: usize = 0, ms: u32 = 0, commit: bool = false };
pub const Run = struct { env: inpu.Env, store: ?*stat.Stat, base: []const u8, done: u32 = 0, crossed: bool = false, hltk: ?halt.Halt = null, cool: bool = false };
fn secs(run: *Run) void { const lo = @as(u64, run.env.conf.acti_dely_secs[0]) * 1000; const hi = @as(u64, run.env.conf.acti_dely_secs[1]) * 1000; const mul: u64 = if (run.cool) 2 else 1; pace.nap(run.env.page.iozz, pace.logn(run.env.rng, lo, hi) * mul, run.env.conf.time_scal_perc); }
fn armz(run: *Run) void { run.env.page.arm(run.env.conf.brow_time_seco * 1000); }
fn dlgText(run: *Run) []const u8 { return run.env.page.evalStr(run.env.aren, CF.dlgs) catch ""; }
pub fn haltCheck(run: *Run) !void { const aren = run.env.aren; const urlz = run.env.page.urlNow(aren) catch return; const txt = run.env.page.textNow(aren) catch ""; if (halt.check(urlz, txt, dlgText(run))) |kind| { run.hltk = kind; if (halt.isLogout(kind)) return error.NeedLogin; if (halt.classOf(kind) == .unsafe) return error.Unsafe; return error.Halted; } }
pub fn peekHalt(page: *pg.Page, aren: std.mem.Allocator) ?halt.Halt { const urlz = page.urlNow(aren) catch return null; const txt = page.textNow(aren) catch ""; const dlg = page.evalStr(aren, CF.dlgs) catch ""; if (halt.check(urlz, txt, dlg)) |kin| return kin; if (page.evalNum(aren, CF.dlgn) > 0) return .overlay; return null; }
fn pauseChk(run: *Run) !void { if (run.store) |sto| { if (sto.flagGet(CF.flag_paus) catch false) return error.Paused; } }
fn findRetry(run: *Run, role: []const u8, labs: []const []const u8, nth: usize) !i64 { var att: u32 = 0; while (att < run.env.conf.retr_coun_maxz) : (att += 1) { armz(run); if (try run.env.page.axFind(run.env.aren, role, labs, nth)) |bid| return bid; try haltCheck(run); pace.nap(run.env.page.iozz, @as(u64, CF.retr_nap) * (att + 1), run.env.conf.time_scal_perc); } return error.NoElement; }
fn clickId(run: *Run, bid: i64) !void { armz(run); try run.env.page.scrollInto(run.env.aren, bid); const pnt = try run.env.page.center(run.env.aren, bid); try inpu.click(&run.env, pnt.x, pnt.y); }
fn clickEl(run: *Run, role: []const u8, labs: []const []const u8, nth: usize) !void { try clickId(run, try findRetry(run, role, labs, nth)); }
fn overlayCheck(run: *Run) !void { var tries: u32 = 0; while (tries < 3) : (tries += 1) { armz(run); if (run.env.page.evalNum(run.env.aren, CF.dlgn) <= 0) return; if (try run.env.page.axFind(run.env.aren, "button", pack.lab(run.env.conf, "popu_dism"), 0)) |bid| { try clickId(run, bid); pace.nap(run.env.page.iozz, 300, run.env.conf.time_scal_perc); continue; } break; } armz(run); if (run.env.page.evalNum(run.env.aren, CF.dlgn) > 0) { run.hltk = .overlay; return error.Halted; } }
fn dwell(run: *Run) void { pace.nap(run.env.page.iozz, pace.logn(run.env.rng, CF.dwel_lo, CF.dwel_hi), run.env.conf.time_scal_perc); if (run.env.rng.span(0, 9) < 3) { armz(run); inpu.scrollBy(&run.env, 120.0) catch {}; } }
fn uploadFile(run: *Run, path: []const u8) !void { const aren = run.env.aren; armz(run); const doc = try run.env.page.call(aren, "DOM.getDocument", "{\"depth\":0}"); const rid = doc.object.get("root").?.object.get("nodeId").?.integer; const qp = try std.json.Stringify.valueAlloc(aren, .{ .nodeId = rid, .selector = "input[type=file]" }, .{}); const qr = try run.env.page.call(aren, "DOM.querySelector", qp); const nid = (qr.object.get("nodeId") orelse return error.NoElement).integer; if (nid == 0) return error.NoElement; const sp = try std.json.Stringify.valueAlloc(aren, .{ .nodeId = nid, .files = [_][]const u8{path} }, .{}); _ = try run.env.page.call(aren, "DOM.setFileInputFiles", sp); }
fn expectTxt(run: *Run, stp: Step) !void { const tot: u32 = if (stp.ms == 0) CF.expe_dflt else stp.ms; var wtd: u32 = 0; while (true) { armz(run); const txt = run.env.page.textNow(run.env.aren) catch ""; if (try fld.matchAny(run.env.aren, txt, stp.labs)) return; try haltCheck(run); if (wtd >= tot) return error.Drift; pace.nap(run.env.page.iozz, 250, run.env.conf.time_scal_perc); wtd += 250; } }
fn pickOpt(run: *Run, text: []const u8) !void { const one = [_][]const u8{text}; var att: u32 = 0; while (att < run.env.conf.retr_coun_maxz) : (att += 1) { for (CF.opts) |rol| { armz(run); if (try run.env.page.axFind(run.env.aren, rol, &one, 0)) |bid| { try clickId(run, bid); return; } } try haltCheck(run); pace.nap(run.env.page.iozz, @as(u64, CF.retr_nap) * (att + 1), run.env.conf.time_scal_perc); } return error.NoElement; }
fn isOn(run: *Run, bid: i64) !bool { const aren = run.env.aren; armz(run); const rp = try std.json.Stringify.valueAlloc(aren, .{ .backendNodeId = bid }, .{}); const rr = try run.env.page.call(aren, "DOM.resolveNode", rp); const obj = rr.object.get("object") orelse return error.CdpError; const oid = (obj.object.get("objectId") orelse return error.CdpError).string; const cp = try std.json.Stringify.valueAlloc(aren, .{ .objectId = oid, .functionDeclaration = CF.ison, .returnByValue = true }, .{}); const cr = try run.env.page.call(aren, "Runtime.callFunctionOn", cp); const res = cr.object.get("result") orelse return error.CdpError; const val = res.object.get("value") orelse return false; return val == .bool and val.bool; }
fn toggleEl(run: *Run, stp: Step) !void { const want = !std.mem.eql(u8, stp.text, "off"); const bid = (run.env.page.axFind(run.env.aren, "checkbox", stp.labs, stp.nth) catch null) orelse (run.env.page.axFind(run.env.aren, "switch", stp.labs, stp.nth) catch null) orelse try findRetry(run, "checkbox", stp.labs, stp.nth); if ((try isOn(run, bid)) != want) try clickId(run, bid); }
pub fn runSteps(run: *Run, steps: []const Step) !void { for (steps) |stp| { try pauseChk(run); if (stp.commit) run.crossed = true; switch (stp.op) { .goto => { secs(run); armz(run); const urlz = if (std.mem.startsWith(u8, stp.text, "http")) stp.text else try std.fmt.allocPrint(run.env.aren, "{s}{s}", .{ run.base, stp.text }); try run.env.page.navigate(run.env.aren, urlz); try haltCheck(run); try overlayCheck(run); dwell(run); }, .click, .confirm => { secs(run); try clickEl(run, if (stp.role.len > 0) stp.role else "button", stp.labs, stp.nth); try haltCheck(run); }, .typez => { secs(run); try clickEl(run, if (stp.role.len > 0) stp.role else "textbox", stp.labs, stp.nth); armz(run); try inpu.typeText(&run.env, stp.text); }, .clear => { secs(run); try clickEl(run, if (stp.role.len > 0) stp.role else "textbox", stp.labs, stp.nth); armz(run); try inpu.clearField(&run.env); }, .key => { armz(run); try inpu.pressKey(&run.env, stp.text); run.env.page.nap(150); try haltCheck(run); }, .wait => pace.nap(run.env.page.iozz, stp.ms, run.env.conf.time_scal_perc), .expect => try expectTxt(run, stp), .scroll => { armz(run); try inpu.scrollBy(&run.env, @floatFromInt(stp.ms)); }, .upload => try uploadFile(run, stp.text), .hover => { secs(run); const bid = try findRetry(run, if (stp.role.len > 0) stp.role else "button", stp.labs, stp.nth); armz(run); try run.env.page.scrollInto(run.env.aren, bid); const pnt = try run.env.page.center(run.env.aren, bid); try inpu.moveTo(&run.env, pnt.x, pnt.y); pace.nap(run.env.page.iozz, 500, run.env.conf.time_scal_perc); }, .select => { secs(run); try clickEl(run, stp.role, stp.labs, stp.nth); pace.nap(run.env.page.iozz, 300, run.env.conf.time_scal_perc); try pickOpt(run, stp.text); }, .toggle => { secs(run); try toggleEl(run, stp); }, .dismiss => { armz(run); if (try run.env.page.axFind(run.env.aren, "button", stp.labs, 0)) |bid| try clickId(run, bid); } } run.done += 1; } }
